tests:
test({ sr: 'predugačak tekst se skraćuje', en: 'a text that is too long is shortened' }, () => {
  expect(truncate('Hello world', 8)).toBe('Hello...');
});
test({ sr: 'kratak tekst ostaje isti', en: 'a short text stays the same' }, () => {
  expect(truncate('Hi', 8)).toBe('Hi');
});
test({ sr: 'tekst tačne dužine ostaje isti', en: 'a text of exactly the maximum length stays the same' }, () => {
  expect(truncate('Hello', 5)).toBe('Hello');
});

hiddenTests:
test('the shortest allowed limit', () => {
  expect(truncate('abcdef', 3)).toBe('...');
});
test('one character too long', () => {
  expect(truncate('abcdef', 5)).toBe('ab...');
});
test('an empty text stays empty', () => {
  expect(truncate('', 5)).toBe('');
});
test('the result is never longer than the limit', () => {
  const text = 'The quick brown fox jumps over the lazy dog';
  for (let max = 3; max <= 50; max++) {
    expect(truncate(text, max).length <= max).toBe(true);
  }
});

solutions.code:
function truncate(text, maxLength) {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength - 3) + '...';
}
